// Encapsulation with #private fields (ES2022): enforced by the engine
class BankAccount {
  #balance = 0;                 // private field: invisible outside the class body
  static #count = 0;            // private static field
  owner;                        // public field

  constructor(owner, initial = 0) {
    this.owner = owner;
    this.#deposit(initial);
    BankAccount.#count++;
  }

  #deposit(amount) {            // private method
    if (!Number.isFinite(amount) || amount < 0) throw new RangeError('invalid amount');
    this.#balance += amount;
  }

  deposit(amount) { this.#deposit(amount); return this; }

  withdraw(amount) {
    if (amount > this.#balance) throw new Error('insufficient funds');
    this.#balance -= amount;
    return this;
  }

  get balance() { return this.#balance; }   // read-only accessor, no setter

  static get count() { return BankAccount.#count; }

  static isAccount(obj) { return #balance in obj; } // ergonomic brand check
}

const acct = new BankAccount('Ada', 100);
acct.deposit(50).withdraw(30);
console.log(acct.balance);                 // 120

acct.balance = 1_000_000;                  // no setter: silently ignored (TypeError in strict mode)
console.log(acct.balance);                 // 120

console.log(acct['#balance']);             // undefined: "#balance" is not a property name
console.log(Object.keys(acct));            // [ 'owner' ]
console.log(JSON.stringify(acct));         // {"owner":"Ada"}

try { acct.withdraw(500); } catch (e) { console.log(e.message); } // insufficient funds

console.log(BankAccount.isAccount(acct), BankAccount.isAccount({})); // true false
new BankAccount('Linus');
console.log(BankAccount.count);            // 2

