// ── Inheritance: a fragile base class ──
class CountingSet extends Set {
  added = 0;                       // how many elements did callers add?
  add(value) {
    this.added++;
    return super.add(value);
  }
  addAll(values) {
    for (const v of values) this.add(v);
    return this;
  }
}
const s = new CountingSet(['a', 'b']);   // Set's constructor calls this.add() for each value,
console.log(s.added);                     // 0  but the "added = 0" initialiser runs AFTER super() and resets it
s.addAll(['c', 'd']);
console.log(s.added, s.size);             // 2 4
// The subclass depends on WHEN and WHETHER the parent calls add() internally.
// That coupling to the parent's implementation details is the fragile base class problem.

// ── Composition: wrap a Set instead of extending it ──
class CountingBag {
  #items = new Set();              // has-a Set, not is-a Set
  #added = 0;
  constructor(values = []) { this.addAll(values); }
  add(value) { this.#added++; this.#items.add(value); return this; }
  addAll(values) { for (const v of values) this.add(v); return this; }
  has(value) { return this.#items.has(value); }
  get size() { return this.#items.size; }
  get added() { return this.#added; }
}
const bag = new CountingBag(['a', 'b']).addAll(['c', 'd']);
console.log(bag.added, bag.size);         // 4 4  (we control every code path)

// ── Composing behaviours instead of building a class hierarchy ──
const canFly = (self) => ({ fly: () => `${self.name} flies` });
const canSwim = (self) => ({ swim: () => `${self.name} swims` });
const canQuack = (self) => ({ quack: () => `${self.name}: quack!` });

function makeDuck(name) {
  const self = { name };
  return Object.assign(self, canFly(self), canSwim(self), canQuack(self));
}
function makePenguin(name) {            // swims but cannot fly: no awkward override
  const self = { name };
  return Object.assign(self, canSwim(self));
}
const duck = makeDuck('Donald');
const penguin = makePenguin('Pingu');
console.log(duck.fly(), '|', duck.quack()); // Donald flies | Donald: quack!
console.log(penguin.swim(), '|', typeof penguin.fly); // Pingu swims | undefined

// ── Abstraction: an interface describes WHAT, not HOW ──
interface Shape {
  readonly name: string;
  area(): number;
}

// Abstract class: shared implementation + a hole subclasses must fill
abstract class BaseShape implements Shape {
  abstract readonly name: string;
  abstract area(): number;
  describe(): string {               // template method using the abstract hook
    return `${this.name} with area ${this.area().toFixed(2)}`;
  }
}

class Circle extends BaseShape {
  readonly name = 'circle';
  radius: number;
  constructor(radius: number) { super(); this.radius = radius; }
  area(): number { return Math.PI * this.radius ** 2; }
}

class Rect extends BaseShape {
  readonly name = 'rect';
  w: number;
  h: number;
  constructor(w: number, h: number) { super(); this.w = w; this.h = h; }
  area(): number { return this.w * this.h; }
}

// ── 1. Subtype polymorphism: one call site, many implementations ──
const shapes: BaseShape[] = [new Circle(1), new Rect(2, 3)];
for (const s of shapes) console.log(s.describe());
// circle with area 3.14
// rect with area 6.00

// ── Structural typing: no "implements" needed, the shape just has to match ──
const triangle = { name: 'triangle', area: () => 0.5 * 4 * 3 };
function totalArea(items: Shape[]): number {
  return items.reduce((sum, s) => sum + s.area(), 0);
}
console.log(totalArea([new Rect(2, 3), triangle]).toFixed(1)); // 12.0

// ── 2. Ad-hoc polymorphism: overload signatures (TS) dispatch by argument type ──
function format(value: number): string;
function format(value: Date): string;
function format(value: number | Date): string {
  return typeof value === 'number' ? value.toFixed(2) : value.toISOString().slice(0, 10);
}
console.log(format(3.14159), format(new Date(Date.UTC(2026, 9, 26)))); // 3.14 2026-10-26

// ── 3. Parametric polymorphism: generics work for ANY type T ──
class Stack<T> {
  #items: T[] = [];
  push(item: T): this { this.#items.push(item); return this; }
  pop(): T | undefined { return this.#items.pop(); }
  get size(): number { return this.#items.length; }
}
const nums = new Stack<number>().push(1).push(2);
const words = new Stack<string>().push('hi');
console.log(nums.pop(), words.pop(), nums.size); // 2 hi 1

// Bounded generic: T must at least look like a Shape
function largest<T extends Shape>(items: T[]): T {
  return items.reduce((a, b) => (b.area() > a.area() ? b : a));
}
console.log(largest([new Circle(2), new Rect(3, 3)]).name); // circle

// ── The same hierarchy written twice: class syntax vs raw prototypes ──
class Animal {
  constructor(name) { this.name = name; }
  speak() { return `${this.name} makes a sound`; }
}
class Dog extends Animal {
  speak() { return `${super.speak()} — woof`; }
}

function AnimalFn(name) { this.name = name; }
AnimalFn.prototype.speak = function () { return `${this.name} makes a sound`; };
function DogFn(name) { AnimalFn.call(this, name); }          // "super(name)"
Object.setPrototypeOf(DogFn.prototype, AnimalFn.prototype);   // "extends" for instances
Object.setPrototypeOf(DogFn, AnimalFn);                       // "extends" for statics
DogFn.prototype.speak = function () {
  return `${AnimalFn.prototype.speak.call(this)} — woof`;     // "super.speak()"
};

const rex = new Dog('Rex');
const fido = new DogFn('Fido');
console.log(rex.speak());   // Rex makes a sound — woof
console.log(fido.speak());  // Fido makes a sound — woof

// ── class is (mostly) sugar: it is still a function with a prototype ──
console.log(typeof Dog);                                          // function
console.log(Object.getPrototypeOf(rex) === Dog.prototype);        // true
console.log(Object.getPrototypeOf(Dog.prototype) === Animal.prototype); // true
console.log(Object.hasOwn(rex, 'name'), Object.hasOwn(rex, 'speak'));   // true false

// ── Method resolution: walk the chain until the property is found ──
const chain = [];
for (let o = rex; o !== null; o = Object.getPrototypeOf(o)) {
  chain.push(o === rex ? 'rex' : o.constructor.name + '.prototype');
}
console.log(chain.join(' -> ')); // rex -> Dog.prototype -> Animal.prototype -> Object.prototype

// Shadowing: an own property wins over the prototype's method
rex.speak = () => 'I am special';
console.log(rex.speak(), '|', new Dog('Max').speak()); // I am special | Max makes a sound — woof

// Methods live once on the prototype and are shared by all instances
console.log(new Dog('A').speak === new Dog('B').speak); // true

// Patching the prototype affects existing instances immediately
Animal.prototype.eat = function () { return `${this.name} eats`; };
console.log(fido.eat === undefined, rex.eat()); // true Rex eats  (fido's chain is AnimalFn)

// Differences that make class more than sugar:
try { Dog('x'); } catch (e) { console.log(e.constructor.name); } // TypeError: needs new
console.log(Object.keys(Dog.prototype));    // []  (class methods are non-enumerable)
console.log(Object.keys(DogFn.prototype));  // [ 'speak' ]  (assigned methods are enumerable)
